-- Generated by generate_ground_loot.py; do not hand-edit.
-- Gear, gem and material descriptors; preview and production carriers share templates.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS dc_ground_loot_parameter (parameter VARCHAR(64) NOT NULL PRIMARY KEY, d3_value DOUBLE NULL, tuned_value DOUBLE NOT NULL, unit VARCHAR(32) NOT NULL, notes TEXT NOT NULL);
INSERT INTO dc_ground_loot_parameter (parameter,d3_value,tuned_value,unit,notes) VALUES
('carrier_scale',NULL,0.2,'multiplier','tunable PLACEHOLDER; ground-loot-verdict.md verified 62894 at scale 0.2 on Rift Keeper; Retune on the invisible carrier; its model differs from the Keeper'),
('open_world_expiry_seconds',NULL,600,'seconds','tunable PLACEHOLDER; decisions.md 2026-09-17 Ground loot moves into ALPHA; Ten minute placeholder; rift drops last until closure'),
('boss_material_count',NULL,50,'count','tunable; decisions.md 2026-09-17 Rift guardian material drop; One random material among Reusable Parts Arcane Dust Veiled Crystal; pickup credits account'),
('ground_delivery_enabled',NULL,0,'boolean','tunable; ground-loot-delivery brief 2026-09-18; corpse-loot-minimum 2026-09-30 (q-0930-56); Rollback switch: 0 = kills put each player''s drops on the corpse (personal corpse loot); 1 = the old ground carriers')
ON DUPLICATE KEY UPDATE d3_value=VALUES(d3_value),tuned_value=VALUES(tuned_value),unit=VALUES(unit),notes=VALUES(notes);
CREATE TABLE IF NOT EXISTS dc_ground_loot_visual (rarity VARCHAR(16) NOT NULL PRIMARY KEY, plate_level TINYINT UNSIGNED NOT NULL, beam_spell INT UNSIGNED NOT NULL);
REPLACE INTO dc_ground_loot_visual (rarity,plate_level,beam_spell) VALUES
('normal',1,0),
('magic',2,62893),
('rare',3,62897),
('legendary',4,62894),
('set',5,62895),
('primal',6,63772);
CREATE TABLE IF NOT EXISTS dc_ground_loot_carrier (base_item INT UNSIGNED NOT NULL PRIMARY KEY, creature_entry INT UNSIGNED NOT NULL UNIQUE);
-- Clone stock schema rather than depending on creature_template column defaults.
-- Engine bitmasks: unit_flags NON_ATTACKABLE|IMMUNE_TO_PC|IMMUNE_TO_NPC = 770;
-- flags_extra TRIGGER|NO_TAUNT|CANNOT_ENTER_COMBAT = 8576; npcflag SPELLCLICK = 16777216.
CREATE TABLE IF NOT EXISTS dc_ground_loot_material (entry INT UNSIGNED NOT NULL PRIMARY KEY,rarity VARCHAR(16) NOT NULL);
REPLACE INTO dc_ground_loot_material(entry,rarity) VALUES (102001,'normal'),(102002,'magic'),(102003,'rare');
